/**
 * A structural edit: add a row or column at a fractional position, delete
 * one by id, or restore a deleted one (an undo). Every op is one write,
 * however many cells the sheet holds.
 */
@Serializable(with = AxisOpSerializer::class)
sealed class AxisOp {
    data class InsertRow(val value: AxisOp_InsertRow) : AxisOp()

    data class InsertCol(val value: AxisOp_InsertCol) : AxisOp()

    data class DeleteRow(val value: AxisOp_DeleteRow) : AxisOp()

    data class DeleteCol(val value: AxisOp_DeleteCol) : AxisOp()

    data class RestoreRow(val value: AxisOp_RestoreRow) : AxisOp()

    data class RestoreCol(val value: AxisOp_RestoreCol) : AxisOp()
}

internal object AxisOpSerializer : KSerializer<AxisOp> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: AxisOp) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            is AxisOp.InsertRow -> JsonObject(mapOf("name" to JsonPrimitive("InsertRow"), "payload" to json.encodeToJsonElement(serializer<AxisOp_InsertRow>(), value.value)))
            is AxisOp.InsertCol -> JsonObject(mapOf("name" to JsonPrimitive("InsertCol"), "payload" to json.encodeToJsonElement(serializer<AxisOp_InsertCol>(), value.value)))
            is AxisOp.DeleteRow -> JsonObject(mapOf("name" to JsonPrimitive("DeleteRow"), "payload" to json.encodeToJsonElement(serializer<AxisOp_DeleteRow>(), value.value)))
            is AxisOp.DeleteCol -> JsonObject(mapOf("name" to JsonPrimitive("DeleteCol"), "payload" to json.encodeToJsonElement(serializer<AxisOp_DeleteCol>(), value.value)))
            is AxisOp.RestoreRow -> JsonObject(mapOf("name" to JsonPrimitive("RestoreRow"), "payload" to json.encodeToJsonElement(serializer<AxisOp_RestoreRow>(), value.value)))
            is AxisOp.RestoreCol -> JsonObject(mapOf("name" to JsonPrimitive("RestoreCol"), "payload" to json.encodeToJsonElement(serializer<AxisOp_RestoreCol>(), value.value)))
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): AxisOp {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        val fields = element.jsonObject
        val tag = fields["name"]?.jsonPrimitive?.content
        return when (tag) {
            "InsertRow" -> AxisOp.InsertRow(json.decodeFromJsonElement(serializer<AxisOp_InsertRow>(), fields["payload"] ?: JsonNull))
            "InsertCol" -> AxisOp.InsertCol(json.decodeFromJsonElement(serializer<AxisOp_InsertCol>(), fields["payload"] ?: JsonNull))
            "DeleteRow" -> AxisOp.DeleteRow(json.decodeFromJsonElement(serializer<AxisOp_DeleteRow>(), fields["payload"] ?: JsonNull))
            "DeleteCol" -> AxisOp.DeleteCol(json.decodeFromJsonElement(serializer<AxisOp_DeleteCol>(), fields["payload"] ?: JsonNull))
            "RestoreRow" -> AxisOp.RestoreRow(json.decodeFromJsonElement(serializer<AxisOp_RestoreRow>(), fields["payload"] ?: JsonNull))
            "RestoreCol" -> AxisOp.RestoreCol(json.decodeFromJsonElement(serializer<AxisOp_RestoreCol>(), fields["payload"] ?: JsonNull))
            else -> throw SerializationException("Unknown AxisOp variant " + tag)
        }
    }
}

