/**
 * A cell, by row and column id. An implicit id is a 0-based position
 * (`"3"` is the fourth row until rows move); the client places ids with the
 * sheet's layout (`get_layouts`).
 */
@Serializable
data class Cell(
    val id: String,
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("row_id") val rowId: String,
    @SerialName("col_id") val colId: String,
    /** As stored: references name rows and columns by id. */
    @SerialName("raw_value") val rawValue: String,
    @SerialName("computed_value") val computedValue: String,
    val format: String,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
    /**
     * Member id of whoever last changed the cell; empty for a cell last
     * written before the activity log existed.
     */
    @SerialName("last_editor") val lastEditor: String,
    @SerialName("last_edited_at") @Serializable(with = U64String::class) val lastEditedAt: ULong,
)

/**
 * One cell's change within an activity entry: its raw value and format
 * before and after.
 */
@Serializable
data class CellChange(
    @SerialName("row_id") val rowId: String,
    @SerialName("col_id") val colId: String,
    @SerialName("before_raw") val beforeRaw: String,
    @SerialName("before_format") val beforeFormat: String,
    @SerialName("after_raw") val afterRaw: String,
    @SerialName("after_format") val afterFormat: String,
)

/**
 * A cell's value, stored in the shared UnorderedMap under
 * `"{sheet_id}|{row_id}|{col_id}"`. Its format is a separate field
 * (`formats`), so a value edit and a format edit never overwrite each other.
 */
@Serializable
data class CellData(
    /** Mirrors the map key for ABI convenience. */
    val id: String,
    @SerialName("sheet_id") val sheetId: String,
    /** Raw user input (may be a formula like `=SUM(A1:A5)`). */
    @SerialName("raw_value") val rawValue: String,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/** Who last changed a cell and when, keyed like the cell. */
@Serializable
data class CellMeta(
    /** Member id (`whoami`). */
    val author: String,
    @Serializable(with = U64String::class) val at: ULong,
)

