    override fun serialize(encoder: Encoder, value: CellOp) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            is CellOp.Set -> JsonObject(mapOf("name" to JsonPrimitive("Set"), "payload" to json.encodeToJsonElement(serializer<CellOp_Set>(), value.value)))
            is CellOp.Format -> JsonObject(mapOf("name" to JsonPrimitive("Format"), "payload" to json.encodeToJsonElement(serializer<CellOp_Format>(), value.value)))
            is CellOp.Clear -> JsonObject(mapOf("name" to JsonPrimitive("Clear"), "payload" to json.encodeToJsonElement(serializer<CellOp_Clear>(), value.value)))
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): CellOp {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        val fields = element.jsonObject
        val tag = fields["name"]?.jsonPrimitive?.content
        return when (tag) {
            "Set" -> CellOp.Set(json.decodeFromJsonElement(serializer<CellOp_Set>(), fields["payload"] ?: JsonNull))
            "Format" -> CellOp.Format(json.decodeFromJsonElement(serializer<CellOp_Format>(), fields["payload"] ?: JsonNull))
