 * The project's own identity, as the UI titles it.
 *
 * `init_project` has always written `project_name`, and until now NOTHING
 * could read it back — there was no view method over the register at all. That
 * is the whole reason the workspace list fell back to names cached in
 * `localStorage`, which meant every peer but the creator saw "Workspace 1".
 */
@Serializable
data class Project(
    /** Fixed when the workbook is created. */
    val id: String,
    /** Empty until `init_project` runs. */
    val name: String,
    @SerialName("created_at") @Serializable(with = U64String::class) val createdAt: ULong,
)

/** A live protected range. */
@Serializable
data class Protection(
    val id: String,
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    val description: String,
    val editors: List<String>,
    @SerialName("created_by") val createdBy: String,
)

/**
 * A protected range: only owners and the listed editors may change its cells.
 * Corners are row and column ids, so the range follows its cells as rows and
 * columns move; all four empty protects the whole sheet. Keyed by id.
 */
@Serializable
data class ProtectionData(
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    val description: String,
    /** Member ids allowed to edit it besides owners. */
    val editors: List<String>,
    @SerialName("created_by") val createdBy: String,
    val deleted: Boolean,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/** A live publication. */
@Serializable
data class Publication(
    val id: String,
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    @SerialName("target_context") val targetContext: String,
    val name: String,
    @SerialName("created_by") val createdBy: String,
)

/**
 * A range this workbook pushes to another workbook in the workspace (the
 * source side of a link). Keyed by id, owned by whoever linked it.
 */
@Serializable
data class PublicationData(
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    /** The receiving workbook's context id, hex. */
    @SerialName("target_context") val targetContext: String,
    /** What the linked sheet is called there. */
    val name: String,
)

/** A live rule. */
@Serializable
data class Rule(
    val id: String,
    val rule: RuleInput,
    @SerialName("created_by") val createdBy: String,
)

/**
 * A conditional format, colour scale or validation over a range, anchored on
 * corner row and column ids like a protected range. Keyed by id.
 */
@Serializable
data class RuleData(
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    /** `format`, `scale` or `validate`. */
    val kind: String,
    val condition: String,
    val args: List<String>,
    /** The style a matching `format` rule applies, as (field, value) pairs. */
    val style: List<StylePair>,
    /** A `validate` rule that refuses values instead of marking them. */
    val strict: Boolean,
    /** Who an `alert` rule tells (member ids). */
    val recipients: List<String>,
    @SerialName("created_by") val createdBy: String,
    val deleted: Boolean,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/** A rule as written or read: its range by corner ids, and what it does. */
@Serializable
data class RuleInput(
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("top_row_id") val topRowId: String,
    @SerialName("left_col_id") val leftColId: String,
    @SerialName("bottom_row_id") val bottomRowId: String,
    @SerialName("right_col_id") val rightColId: String,
    /**
     * `format` (style cells that meet the condition), `scale` (shade numbers
     * from `args[0]` at the lowest to `args[1]` at the highest), `validate`
     * (values must meet the condition) or `alert` (tell `recipients` when a
     * value starts meeting it).
     */
    val kind: String,
    val condition: String,
    val args: List<String>,
    val style: Map<String, String>,
    val strict: Boolean,
    val recipients: List<String>,
)

@Serializable
data class Sheet(
    val id: String,
    val name: String,
    val position: UInt,
    @SerialName("created_at") @Serializable(with = U64String::class) val createdAt: ULong,
    /**
     * For a linked sheet (read-only, pushed from another workbook), that
     * workbook's name; empty otherwise.
     */
    @SerialName("linked_from") val linkedFrom: String,
)

/** A sheet tab stored in the shared UnorderedMap. */
@Serializable
data class SheetData(
    val id: String,
    val name: String,
    /** Tab ordering hint (lower = further left). */
    val position: UInt,
    @SerialName("created_at") @Serializable(with = U64String::class) val createdAt: ULong,
    /** Timestamp of the last rename — used for LWW name merge. */
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/**
 * A sheet's explicit row and column entries. A sheet with none has the
 * implicit layout: row id `k` at row `k`.
 */
@Serializable
data class SheetLayout(
    @SerialName("sheet_id") val sheetId: String,
    val rows: List<AxisEntryView>,
    val cols: List<AxisEntryView>,
)

/** A sheet's frozen rows and columns and resized rows and columns. */
@Serializable
data class SheetView(
    @SerialName("sheet_id") val sheetId: String,
    @SerialName("frozen_rows") val frozenRows: UInt,
    @SerialName("frozen_cols") val frozenCols: UInt,
    val sizes: List<AxisSize>,
)

/** How a sheet is shown: its frozen rows and columns. Keyed by sheet id. */
@Serializable
data class SheetViewData(
    @SerialName("frozen_rows") val frozenRows: UInt,
    @SerialName("frozen_cols") val frozenCols: UInt,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/** A resized row or column. Keyed `"{sheet_id}|r|{id}"` or `"{sheet_id}|c|{id}"`. */
@Serializable
data class SizeData(
    /** Pixels. */
    val size: UInt,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

@Serializable
data class Span(
    val text: String,
    val attributes: Map<String, String>,
)

@Serializable
data class Spreadsheet(
    /** The workbook's id and creation time, fixed in `init`. */
    val founding: Founding,
    /**
     * The workbook's name, set by `init_project`; empty until then. Only
     * owners write it.
     */
    @SerialName("project_name") val projectName: String,
    /**
     * Workbook roles. Its admins are the owners; `viewer` and `commenter`
     * are named roles. A member with neither and not an owner is an editor.
     */
    val acl: Map<String, Boolean>,
    /** Sheet tabs keyed by sheet id. */
    val sheets: Map<String, SheetData>,
    /**
     * Cell values keyed by `"{sheet_id}|{row_id}|{col_id}"`, so one sheet's
     * cells are one prefix.
     */
    val cells: Map<String, CellData>,
    /** Chosen nicknames, one slot per account that only it writes. */
    val members: Map<String, MemberData>,
    /**
     * Added and deleted rows and columns, keyed `"{sheet_id}|r|{id}"` and
     * `"{sheet_id}|c|{id}"`.
     */
    val axes: Map<String, AxisData>,
    /** Cell formats, keyed like `cells`. */
    val formats: Map<String, FormatData>,
    /** Named ranges keyed by upper-case name. */
    val names: Map<String, NamedRangeData>,
    /** Who last changed each cell, keyed like `cells`. */
    @SerialName("cell_meta") val cellMeta: Map<String, CellMeta>,
    /** The activity log: each entry owned by its author and never changed. */
    val activity: Map<String, ActivityData>,
    /**
     * Cell comments and replies, keyed by comment id: the author edits and
     * deletes, owners (the moderators) delete.
     */
    val comments: Map<String, CommentData>,
    /**
     * Whether a comment's thread is resolved, keyed by comment id. Anyone
     * in the workbook may resolve, so it is not part of the comment.
     */
    val resolved: Map<String, Boolean>,
    /**
     * Cell notes, keyed like `cells`: rich text that merges concurrent edits
     * character by character.
     */
    val notes: Map<String, Map<String, Span>>,
    /** Protected ranges, keyed by id. Only owners write them. */
    val protections: Map<String, ProtectionData>,
    /** Resized rows and columns, keyed like `axes`. */
    val sizes: Map<String, SizeData>,
    /** Frozen rows and columns per sheet. */
    val views: Map<String, SheetViewData>,
    /** Cell styles, keyed like `cells`. */
    val styles: Map<String, StyleData>,
    /** Conditional formats, colour scales and validations, keyed by id. */
    val rules: Map<String, RuleData>,
    /** Charts, keyed by id. */
    val charts: Map<String, ChartData>,
    /**
     * Files attached to cells, keyed by id: whoever attached one removes
     * it, and owners (the moderators) may.
     */
    val attachments: Map<String, AttachmentData>,
    /**
     * Ranges this workbook pushes to others, keyed by id: whoever linked
     * one stops it, and owners (the moderators) may.
     */
    val publications: Map<String, PublicationData>,
    /** Ranges pushed here from other workbooks, keyed by linked sheet id. */
    val linked: Map<String, LinkedData>,
    /** Alert rules' last matching cells, keyed by rule id. */
    @SerialName("alert_state") val alertState: Map<String, AlertState>,
)

/**
 * A cell's style, one last-writer-wins value per field, so one person
 * making a cell bold and another colouring it both keep their change.
 * Keyed like `cells`.
 */
@Serializable
data class StyleData(
    /** One entry per field, sorted by field. An empty value is a cleared field. */
    val fields: List<StyleField>,
)

@Serializable
data class StyleField(
    val field: String,
    val value: String,
    @SerialName("updated_at") @Serializable(with = U64String::class) val updatedAt: ULong,
)

/** One style change: set `field` of a cell to `value` (empty clears it). */
@Serializable
data class StyleOp(
    @SerialName("row_id") val rowId: String,
    @SerialName("col_id") val colId: String,
    val field: String,
    val value: String,
)

@Serializable
data class StylePair(
    val field: String,
    val value: String,
)

/**
 * Fixed-size bytes. An id with its own spelling (`UserId`, `BlobId`) is [Text] —
 * base58 or hex, exactly as the contract writes it — and a plain `[u8; N]` is
 * [Raw], an array of numbers. Decoding takes whichever arrives; encoding writes
 * the form this value holds.
 */
@Serializable(with = ContractBytesSerializer::class)
sealed class ContractBytes {
    data class Text(val value: String) : ContractBytes()

    data class Raw(val value: List<UByte>) : ContractBytes()

    /** The text form, if that is what this holds. */
    val text: String? get() = (this as? Text)?.value

    /** The array form, if that is what this holds. */
    val raw: List<UByte>? get() = (this as? Raw)?.value
}

internal object ContractBytesSerializer : KSerializer<ContractBytes> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: ContractBytes) {
        val element = when (value) {
            is ContractBytes.Text -> JsonPrimitive(value.value)
            is ContractBytes.Raw -> JsonArray(value.value.map { JsonPrimitive(it.toInt()) })
        }
        (encoder as JsonEncoder).encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): ContractBytes {
        val element = (decoder as JsonDecoder).decodeJsonElement()
        return if (element is JsonPrimitive && element.isString) {
            ContractBytes.Text(element.content)
        } else {
            ContractBytes.Raw(element.jsonArray.map { it.jsonPrimitive.content.toInt().toUByte() })
        }
    }
}

/** The JSON the contract speaks. */
val sheetsJson = Json { ignoreUnknownKeys = true }

/** An answer of the generated client as the workbook type [T]. */
inline fun <reified T> JsonElement.toSheets(): T = sheetsJson.decodeFromJsonElement(serializer<T>(), this)
